begin;
insert into public.categories (id,name,description,image,artwork,sort_order) select id,name,description,image,artwork,sort_order from jsonb_to_recordset('[{"id":"telefona","name":"iPhone & telefona","image":"phone-17-pro-orange.webp","description":"Nga iPhone Air te modelet Pro. Gjej telefonin tënd të ardhshëm.","artwork":["phone-15-pro-blue.webp","phone-17-lavender.webp","phone-17-pro-orange.webp","phone-air-blue.webp"],"sort_order":0},{"id":"motore","name":"Motorë elektrikë","image":"moto-niu.webp","description":"Dy rrota elektrike për rrugët e përditshme.","artwork":["moto-niu.webp"],"sort_order":1},{"id":"trotineta","name":"Trotineta elektrikë","image":"scooter-g2-side.webp","description":"Lëviz me ritmin tënd, kudo në qytet.","artwork":["scooter-g2-side.webp","scooter-g2.webp"],"sort_order":2},{"id":"tableta","name":"Tableta","image":"tablet-air-blue.webp","description":"Për të punuar, krijuar dhe mësuar në lëvizje.","artwork":["tablet-air-purple.webp","tablet-air-blue.webp"],"sort_order":3},{"id":"aksesore","name":"Aksesorë","image":"audio-airpods-pro-3.webp","description":"Tingull, orë inteligjente dhe detajet e përditshme.","artwork":["watch-se-3.webp","audio-airpods-pro-3.webp"],"sort_order":4}]'::jsonb) as x(id text,name text,description text,image text,artwork jsonb,sort_order integer) on conflict (id) do nothing;
insert into public.products (id,category,name,description,image,specs,views,finishes,published,is_demo,sort_order) select id,category,name,description,image,specs,views,finishes,published,is_demo,sort_order from jsonb_to_recordset('[{"id":"iphone-17","name":"iPhone 17","category":"telefona","image":"phone-17-lavender.webp","description":"Një vështrim në iPhone 17 në ngjyrën Lavender. Pyet dyqanin për kapacitetet dhe ngjyrat e disponueshme.","specs":[["Marka","Apple"],["Modeli","iPhone 17"],["Ngjyra në foto","Lavender"]],"published":true,"is_demo":true,"sort_order":0},{"id":"iphone-air","name":"iPhone Air","category":"telefona","image":"phone-air-blue.webp","description":"Eksploro iPhone Air në Sky Blue. Kontakto dyqanin për detajet e modelit që të intereson.","specs":[["Marka","Apple"],["Modeli","iPhone Air"],["Ngjyra në foto","Sky Blue"]],"published":true,"is_demo":true,"sort_order":1},{"id":"kukirin-g2","name":"KuKirin G2","category":"trotineta","image":"scooter-g2.webp","description":"Trotinet elektrik me motor 800 W, goma 10 inç dhe platformë të gjerë për këmbët.","specs":[["Marka","KuKirin"],["Fuqia e motorit","800 W"],["Gomat","10 inç"]],"views":[["Pamje nga këndi","scooter-g2.webp"],["Pamje anësore","scooter-g2-side.webp"]],"published":true,"is_demo":true,"sort_order":2},{"id":"iphone-17-pro","name":"iPhone 17 Pro","category":"telefona","image":"phone-17-pro-orange.webp","description":"iPhone me ekran 6,3 inç, çip A19 Pro dhe kasë alumini në ngjyrën Cosmic Orange.","specs":[["Marka","Apple"],["Ekrani","6,3 inç"],["Çipi","A19 Pro"]],"published":true,"is_demo":true,"sort_order":3},{"id":"ipad-air","name":"iPad Air 11″","category":"tableta","image":"tablet-air-blue.webp","description":"Tablet 11 inç me lidhje Wi-Fi për lexim, shënime dhe punë në lëvizje.","specs":[["Marka","Apple"],["Ekrani","11 inç"],["Lidhja","Wi-Fi"]],"finishes":[["Blu","#a6c0ce","tablet-air-blue.webp"],["Vjollcë","#b7a9c7","tablet-air-purple.webp"]],"published":true,"is_demo":true,"sort_order":4},{"id":"airpods-pro-3","name":"AirPods Pro 3","category":"aksesore","image":"audio-airpods-pro-3.webp","description":"Kufje pa kabllo me anulim aktiv të zhurmës dhe kuti karikimi MagSafe me portë USB-C.","specs":[["Marka","Apple"],["Lloji","Kufje pa kabllo"],["Kutia e karikimit","MagSafe, USB-C"]],"published":true,"is_demo":true,"sort_order":5},{"id":"niu-nqi-sport","name":"NIU NQi Sport","category":"motore","image":"moto-niu.webp","description":"Motor elektrik me ulëse për lëvizje në qytet. Prodhuesi deklaron shpejtësi maksimale 45 km/h.","specs":[["Marka","NIU"],["Shpejtësia maksimale","45 km/h"],["Fuqia maksimale","1 800 W"]],"published":true,"is_demo":true,"sort_order":6},{"id":"iphone-15-pro","name":"iPhone 15 Pro","category":"telefona","image":"phone-15-pro-titanium.webp","description":"iPhone me kornizë titani, ekran 6,1 inç dhe çip A17 Pro. Shiko dy përfundimet e titanit.","specs":[["Marka","Apple"],["Ekrani","6,1 inç"],["Çipi","A17 Pro"]],"finishes":[["Titan natyral","#aaa496","phone-15-pro-titanium.webp"],["Titan blu","#566377","phone-15-pro-blue.webp"]],"published":true,"is_demo":true,"sort_order":7},{"id":"watch-se-3","name":"Apple Watch SE 3","category":"aksesore","image":"watch-se-3.webp","description":"Orë inteligjente me kasë alumini në ngjyrën Starlight për të ndjekur aktivitetin e përditshëm.","specs":[["Marka","Apple"],["Lloji","Orë inteligjente"],["Ngjyra","Starlight"]],"published":true,"is_demo":true,"sort_order":8}]'::jsonb) as x(id text,category text,name text,description text,image text,specs jsonb,views jsonb,finishes jsonb,published boolean,is_demo boolean,sort_order integer) on conflict (id) do nothing;
update public.homepage_settings set featured_product_id='kukirin-g2', collection_product_ids=array['kukirin-g2','iphone-17-pro','ipad-air','airpods-pro-3','niu-nqi-sport','iphone-15-pro','watch-se-3'] where id=1;
commit;
